select g_id id, g_name name,g_sellNum sellNumber, g_price price, g_number number, s_id shopID, c3_name class3, g_imgNum imgNumber, g_img1 goodsImg1, g_img2 goodsImg2, g_img3 goodsImg3, g_img4 goodsImg4, g_img5 goodsImg5
from goods
